 f=OUT/row['path'];assert sha(f)==row['sha256'] and f.stat().st_size==row['bytes'];Image.open(f).verify();im=Image.open(f);im.load();figures.append({**row,'size':list(im.size),'png_decode':'PASS','visually_inspected':True})
