assert all(r['raw_pearson']is not None and r['normalized_rms']is not None and r['raw_pearson_block_reason']is None and r['normalized_rms_block_reason']is None and r['common_finite_raw_samples']==(51 if r['region']=='core' else 550) and r['common_finite_normalized_samples']==(51 if r['region']=='core' else 550) for r in C)
assert P['target']=='HD114386' and P['group_center_bary_air_angstrom']==3869.915 and P['anchor_dp_id']=='ADP.2022-05-17T01:02:16.724' and P['anchor_berv_km_s']==-10.767337430651
handoff=read(REPO/'work_harps_20261103_c016_context/NEXT_ACTION.json');assert P['merged_dp_ids']==[r['dp_id'] for r in handoff['existing_cohort_epochs']] and P['discovery_dp_ids']==[P['anchor_dp_id']]
assert {P['historical_review_disagreement'][k] for k in ['primary_code','secondary_code','root_adopted_code']}=={'U'}
fields=['original_grid_mapping_usable','original_local_mapping_usable','original_baseline_mapping_verified','final_reference_mapping_supported'];assert len(P['historical_mapping_stages'])==1 and P['historical_mapping_stages'][0]['order']==3 and all(P['historical_mapping_stages'][0][k]is True for k in fields)
