assert len(P['prior_bounded_window_geometry'])==13 and not any(r['shared_source_pixels'] for r in P['prior_bounded_window_geometry'])
assert [r['group'] for r in P['prior_bounded_window_geometry'] if not r['numerically_disjoint_from_C015']]==['C002','C003','C004','C011','C012']
merged=[r for r in R if r['kind']=='merged'];native=[r for r in R if r['kind']=='native'];assert len(merged)==14 and len(native)==2
