assert all(r['order']==3 and r['window_native_finite_samples']==550 and r['left_flank_finite_samples']==135 and r['right_flank_finite_samples']==140 and r['window_nonpositive_fraction']==0 and r['left_flank_nonpositive_fraction']==0 and r['right_flank_nonpositive_fraction']==0 for r in native)
