assert sum(r['window_nonpositive_fraction']==0 and r['left_flank_nonpositive_fraction']==0 and r['right_flank_nonpositive_fraction']==0 for r in R)==14
nonself=[r for r in C if r['relationship']=='MERGED_EPOCH_TO_DISCOVERY' and not r['identical_product_self_pair']];by={(r['dp_id'],r['frame'],r['region']):r for r in nonself};other=[d for d in P['merged_dp_ids'] if d!=P['anchor_dp_id']]
for dp in other:
 for z in ['core','broad_pattern']:
  assert by[dp,'barycentric',z]['raw_pearson']>by[dp,'topocentric',z]['raw_pearson'];assert by[dp,'barycentric',z]['normalized_rms']<by[dp,'topocentric',z]['normalized_rms']
topcore=[r for r in nonself if r['frame']=='topocentric' and r['region']=='core'];assert sum(r['raw_pearson']<0 for r in topcore)==5 and [r['dp_id'] for r in topcore if r['raw_pearson']>0]==['ADP.2022-01-12T01:34:46.931']
aug=P['merged_dp_ids'][-1]
for z in ['core','broad_pattern']:
 rows=[r for r in nonself if r['frame']=='barycentric' and r['region']==z];assert min(rows,key=lambda r:r['raw_pearson'])['dp_id']==max(rows,key=lambda r:r['normalized_rms'])['dp_id']==aug
