assert [m['candidate_id'] for m in members]==['V2E2-0114','V2E2-0119','V2E2-0124','V2E2-0128','V2E2-0133','V2E2-0134','V2E2-0138']
history=next(r for r in N['historical_review_disagreement']['per_event_history'] if r['candidate_id']=='V2E2-0128');assert history['original_primary_code']=='I' and history['original_secondary_code']=='M' and history['original_secondary_normalized_code']=='I' and history['original_adopted_baseline_code']=='I' and history['later_mapping_followup_primary_code']==history['later_mapping_followup_secondary_code']==history['current_adopted_code']=='U' and history['coordinates_changed']is False
assert N['completed_mapping_followup_dependency']['original_order2_local_and_mapping_verified']is False and N['completed_mapping_followup_dependency']['later_both_order_reference_support']is True and N['completed_mapping_followup_dependency']['no_replay']is True
report=(HERE/'RESULTS_REPORT.md').read_text()
for text in ['V2E2-0095 remains U','16 profiles and 32 comparison slots','all six pairs in each region','0.827496','0.641368','0.785728','0.347069','16 false low-reference flags','1/600 window samples','1/150 right-flank samples','14 profile rows','550 finite original window samples','0.047010202 Å below','U/U/U','C018 / R019','all seven original members','primary I, secondary M (normalized I), adopted baseline I','failed original order-2 local/mapping stage','No C018 array analysis']:
 assert text in report,text
links=re.findall(r'\]\(([^)]+)\)',report);assert not [q for q in links if not(HERE/q).exists() and not q.startswith('http') and q!='RESULTS_QA.json']
audit=read(HERE.parent/'independent_audit/NUMERICAL_AUDIT.json');assert audit['status'].startswith('PASS') and audit['checks_passed']==455 and audit['scalar_values_compared']==63724
qa={'status':'PASS_COMPLETE_C015_RESULT_DELIVERY','checked_utc':datetime.datetime.now(datetime.timezone.utc).isoformat(),'target':'HD114386','exact_catalog_center':3869.915,'original_core_bary_air_angstrom':[3869.665,3870.165],'singleton_reference_and_marker_restored':True,'anchor_dp_id':P['anchor_dp_id'],'anchor_berv_km_s':P['anchor_berv_km_s'],'frozen_source_hashes_verified':56,'public_method_bindings_verified':25,'numerical_output_hashes_verified':35,'numerical_npz_files_verified':25,'stable_numeric_ledger_sha256':sha(OUT/'OUTPUT_HASHES.json'),'profile_slots':16,'comparison_slots':32,'identical_product_self_comparisons':4,'distinct_discovery_products':1,'bounded_source_windows':8,'preserved_raw_copies':1,'full_profiles_with_valid_positive_reference':16,'false_low_reference_flags':16,'true_low_reference_flags':0,'null_low_reference_flags':0,'raw_only_profiles':0,'blocked_profiles':0,'structurally_excluded_native_orders':0,'evaluable_Pearson':32,'unavailable_Pearson':0,'evaluable_RMS':32,'unavailable_RMS':0,'all_comparisons_complete_raw_and_normalized_support':True,'all_profiles_zero_positive_ERR':True,'profiles_with_nonpositive_signed_window_samples':2,'profiles_with_zero_nonpositive_window_and_flank_fractions':14,'nonpositive_epoch':'2023-01-02','nonpositive_source_window_counts':[1,1],'finite_source_window_counts':[600,600],'nonpositive_right_flank_counts':[1,1],'finite_right_flank_counts':[150,150],'all_left_flank_nonpositive_fractions_zero':True,'merged_finite_source_window_samples':600,'native_finite_source_window_samples':550,'native_finite_left_right_flank_samples':[135,140],'all_profiles_zero_gap_and_outside_coverage_masks':True,'all_six_nonself_comparisons_better_barycentric_both_metrics_each_region':True,'negative_topocentric_nonself_core_correlations':5,'positive_topocentric_core_epoch':'2022-01-06','August_2023_lowest_barycentric_r_and_largest_RMS_both_regions_retained':True,'historical_review_codes_preserved':'U/U/U','order3_all_four_mapping_stages_true_preserved':True,'predicted_centers_outside_fixed_topocentric_core':3,'outside_predicted_center_dates':outside,'center_flags_not_full_feature_coverage_claims':True,'other_target_numeric_overlap_no_shared_pixels_preserved':True,'original_evidence_and_same_target_disjoint_window_dependence_acknowledged':True,'figures':figures,'all_four_figures_visually_inspected':True,'report_links_verified':len(links),'report_sha256':sha(HERE/'RESULTS_REPORT.md'),'plot_index_sha256':sha(OUT/'PLOT_INDEX.json'),'independent_actual_audit_sha256':sha(HERE.parent/'independent_audit/NUMERICAL_AUDIT.json'),'next_group':'C018','next_target':'HD114783','next_member_count':7,'next_0128_original_I_M_normalized_I_then_later_U_history_preserved':True,'next_0128_failed_original_stage_not_repaired_by_later_support':True,'completed_mapping_and_normalization_no_replay_preserved':True,'method_or_numerical_mutations':0,'labels_changed':0,'notes':['Exact singleton center/core, one May2022 reference and order3 restored without C016 joint design or quality transfer.','Only January2 2023 retains one nonpositive original source sample per frame in its right flank; signed values unchanged.','Native550 original source samples/135,140flanks remain distinct from601 interpolated-grid support.','August lower raw level and stronger scaled variation/poorer barycentric agreement retained; low=false is not a quality certificate.','All six comparisons favor barycentric r and RMS in both regions; five negative and one positive topocentric core correlations retained.','Raw central diffuse trace/excess and strong right-edge residual lobes preserved at full scales without new modeling or origin assignment.','Next C018 retains seven new-target members and references, exact original floating centers and staged0128 history; no blanket original-U claim or replay of completed mapping.']}
